-- CORE_V1 internal evaluation only. No publication or external allocation.
CREATE TABLE app.rubric_versions (
 code text PRIMARY KEY CHECK(code='CORE_V1'), kind text NOT NULL CHECK(kind='internal'),
 schema_version integer NOT NULL CHECK(schema_version=1), config jsonb NOT NULL,
 config_hash text NOT NULL CHECK(config_hash=encode(sha256(convert_to(config::text,'UTF8')),'hex'))
);
CREATE TABLE app.evaluation_cases (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), university_id uuid NOT NULL,project_id uuid NOT NULL,version_id uuid NOT NULL,submission_id uuid NOT NULL UNIQUE,
 rubric_code text NOT NULL REFERENCES app.rubric_versions(code),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(university_id,project_id,version_id,submission_id,id),
 FOREIGN KEY(university_id,project_id,version_id,submission_id) REFERENCES app.project_submissions(university_id,project_id,version_id,id)
);
CREATE TABLE app.internal_assessments (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),university_id uuid NOT NULL,project_id uuid NOT NULL,version_id uuid NOT NULL,submission_id uuid NOT NULL,case_id uuid NOT NULL,
 layer text NOT NULL CHECK(layer IN ('supervisor','committee')),rubric_code text NOT NULL REFERENCES app.rubric_versions(code),rubric_hash text NOT NULL,
 recorded_by uuid NOT NULL,recorded_at timestamptz NOT NULL,finalized_at timestamptz NOT NULL,
 quarter_points integer NOT NULL CHECK(quarter_points BETWEEN 0 AND 400),overall_comment text NOT NULL CHECK(char_length(btrim(overall_comment)) BETWEEN 50 AND 2000),calibration_ack boolean NOT NULL CHECK(calibration_ack),
 member_names jsonb NOT NULL,assessed_on date,attestation boolean NOT NULL,
 CHECK((layer='supervisor' AND member_names='[]'::jsonb AND assessed_on IS NULL AND NOT attestation) OR (layer='committee' AND jsonb_typeof(member_names)='array' AND jsonb_array_length(member_names)>=2 AND assessed_on IS NOT NULL AND attestation)),
 UNIQUE(submission_id,layer),UNIQUE(university_id,project_id,version_id,submission_id,id),
 FOREIGN KEY(university_id,project_id,version_id,submission_id,case_id) REFERENCES app.evaluation_cases(university_id,project_id,version_id,submission_id,id),
 FOREIGN KEY(university_id,recorded_by) REFERENCES app.users(university_id,id)
);
CREATE TABLE app.internal_criterion_scores (
 assessment_id uuid NOT NULL REFERENCES app.internal_assessments(id),code text NOT NULL CHECK(code ~ '^C[1-7]$'),level integer NOT NULL CHECK(level BETWEEN 0 AND 4),comment text NOT NULL CHECK(char_length(btrim(comment))<=1000 AND (level NOT IN (0,4) OR char_length(btrim(comment))>=20)),
 PRIMARY KEY(assessment_id,code)
);
CREATE TABLE app.internal_evidence_locators (
 university_id uuid NOT NULL,project_id uuid NOT NULL,version_id uuid NOT NULL,submission_id uuid NOT NULL,assessment_id uuid NOT NULL,code text NOT NULL,ordinal integer NOT NULL CHECK(ordinal BETWEEN 1 AND 20),file_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('page','section','figure','test','lines')),reference text NOT NULL CHECK(char_length(btrim(reference)) BETWEEN 1 AND 200),
 PRIMARY KEY(assessment_id,code,ordinal),
 FOREIGN KEY(assessment_id,code) REFERENCES app.internal_criterion_scores(assessment_id,code),
 FOREIGN KEY(university_id,project_id,version_id,submission_id,assessment_id) REFERENCES app.internal_assessments(university_id,project_id,version_id,submission_id,id),
 FOREIGN KEY(submission_id,file_id) REFERENCES app.submission_files(submission_id,file_id)
);
CREATE TABLE app.internal_evaluation_issues (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL UNIQUE REFERENCES app.evaluation_cases(id),supervisor_id uuid NOT NULL REFERENCES app.internal_assessments(id),committee_id uuid NOT NULL REFERENCES app.internal_assessments(id),kind text NOT NULL CHECK(kind='internal_disagreement'),created_at timestamptz NOT NULL
);
DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['rubric_versions','evaluation_cases','internal_assessments','internal_criterion_scores','internal_evidence_locators','internal_evaluation_issues'] LOOP
 EXECUTE format('CREATE TRIGGER immutable_evaluation BEFORE UPDATE OR DELETE ON app.%I FOR EACH ROW EXECUTE FUNCTION app.immutable_record()',n);
 EXECUTE format('REVOKE ALL ON app.%I FROM PUBLIC,capstone_runtime,capstone_jobs',n);
END LOOP;END $$;
INSERT INTO app.rubric_versions SELECT 'CORE_V1','internal',1,j,encode(sha256(convert_to(j::text,'UTF8')),'hex') FROM (SELECT '{"code": "CORE_V1", "kind": "internal", "schemaVersion": 1, "criteria": [{"code": "C1", "weight": 10, "label": {"en": "Problem and Objectives", "ar": "المشكلة والأهداف"}, "description": {"en": "Identify a bounded problem and stakeholder; map every declared core objective to an observable success condition and a reported outcome. Evidence: problem statement, objective list, and traceability summary. Assess the declared undergraduate scope, not the size of the institution or market. The problem-to-outcome mapping must be present in the frozen assessed submission.", "ar": "حدد مشكلة محصورة وصاحب مصلحة واربط كل هدف أساسي بشرط نجاح قابل للملاحظة ونتيجة موثقة. الأدلة: بيان المشكلة وقائمة الأهداف وملخص التتبع. قيّم النطاق الجامعي المعلن لا حجم المؤسسة أو السوق؛ يجب أن يكون الربط في اللقطة المجمدة."}, "anchors": [{"level": 0, "en": "No assessable problem or objectives.", "ar": "لا توجد مشكلة أو أهداف قابلة للتقييم."}, {"level": 1, "en": "Broad problem; objectives cannot be checked.", "ar": "المشكلة واسعة والأهداف غير قابلة للتحقق."}, {"level": 2, "en": "Bounded problem and core objectives with identifiable outputs; some success measures are weak.", "ar": "مشكلة محددة وأهداف أساسية ذات مخرجات قابلة للتحديد؛ بعض مقاييس النجاح ضعيفة."}, {"level": 3, "en": "Context-supported need, observable success conditions, and a clear objective-to-result mapping.", "ar": "حاجة يدعمها السياق وشروط نجاح قابلة للملاحظة وربط واضح بين الأهداف والنتائج."}, {"level": 4, "en": "Complete problem → objective → deliverable → measured outcome traceability, with scope and limitations justified.", "ar": "تتبع كامل من المشكلة إلى الهدف والمخرج والنتيجة المقاسة مع تبرير النطاق والقيود."}]}, {"code": "C2", "weight": 20, "label": {"en": "Methodological / Disciplinary Rigor", "ar": "الصرامة المنهجية والتخصصية"}, "description": {"en": "Explain the selected method, material assumptions, and key design/research decisions; justify why the approach fits the problem and identify appropriate alternatives. Evidence: methods/design section and decision rationale. Use disciplinary norms rather than requiring software engineering for every project. Evaluate decisions supported in the submitted evidence, not later promises.", "ar": "اشرح المنهج والافتراضات الجوهرية وقرارات التصميم أو البحث الأساسية وبرر ملاءمته وحدد البدائل المناسبة. الأدلة: قسم المنهج أو التصميم ومبررات القرارات. اتبع أعراف التخصص دون اشتراط هندسة البرمجيات؛ قيّم القرارات المدعومة في اللقطة لا الوعود اللاحقة."}, "anchors": [{"level": 0, "en": "No defensible method.", "ar": "لا توجد منهجية يمكن الدفاع عنها."}, {"level": 1, "en": "Method named but unsuitable or largely unexplained.", "ar": "المنهجية مسماة لكنها غير مناسبة أو غير مشروحة إلى حد كبير."}, {"level": 2, "en": "Suitable method with basic steps and material assumptions documented.", "ar": "منهجية مناسبة مع توثيق الخطوات الأساسية والافتراضات الجوهرية."}, {"level": 3, "en": "Key choices and relevant alternatives are justified with coherent disciplinary reasoning.", "ar": "تبرير الخيارات الأساسية والبدائل ذات الصلة باستدلال تخصصي متماسك."}, {"level": 4, "en": "The reasoning is consistently supported, critical assumptions are examined, and trade-offs/limitations are evidenced.", "ar": "الاستدلال مدعوم باستمرار مع فحص الافتراضات الحاسمة وإثبات المفاضلات والقيود."}]}, {"code": "C3", "weight": 20, "label": {"en": "Implementation and Deliverable Quality", "ar": "جودة التنفيذ والمخرجات"}, "description": {"en": "Demonstrate completion of the declared core deliverables; connect each core objective to an inspectable artifact or result and identify unresolved defects or limitations. A working prototype, research output, design, or analysis can satisfy the criterion within its declared scope. Assess only outputs captured by the submission cutoff.", "ar": "أثبت إتمام المخرجات الأساسية المعلنة واربط كل هدف بمخرج أو نتيجة قابلة للفحص وحدد العيوب أو القيود غير المحلولة. يكفي نموذج أولي أو بحث أو تصميم أو تحليل ضمن النطاق المعلن؛ قيّم المخرجات الملتقطة قبل موعد التسليم فقط."}, "anchors": [{"level": 0, "en": "No inspectable relevant output.", "ar": "لا توجد مخرجات ذات صلة قابلة للفحص."}, {"level": 1, "en": "Major core deliverables absent or unusable.", "ar": "مخرجات أساسية رئيسية غائبة أو غير قابلة للاستخدام."}, {"level": 2, "en": "Main deliverables are inspectable and meet basic declared functions/results, with limitations identified.", "ar": "المخرجات الرئيسية قابلة للفحص وتحقق الوظائف أو النتائج الأساسية المعلنة مع تحديد القيود."}, {"level": 3, "en": "Core objectives are demonstrably met and artifacts are coherent, usable and supported by relevant quality checks.", "ar": "تحقيق الأهداف الأساسية مثبت والمخرجات متماسكة وقابلة للاستخدام ومدعومة بفحوص جودة مناسبة."}, {"level": 4, "en": "Complete scoped deliverables with robust handling of material failure/edge conditions and evidence of consistently high quality.", "ar": "مخرجات كاملة ضمن النطاق مع معالجة متينة لحالات الفشل والحدود الجوهرية وأدلة على جودة عالية متسقة."}]}, {"code": "C4", "weight": 20, "label": {"en": "Validation and Evidence", "ar": "التحقق والأدلة"}, "description": {"en": "Report at least one suitable validation activity with method, data or observations, explicit success conditions, results, and limitations; trace each core claim to the evidence that tests it. Validation depth is proportionate to the project and discipline; no fixed national sample size is imposed. Results and procedures must be recorded in the assessed version.", "ar": "وثق نشاط تحقق مناسباً واحداً على الأقل يتضمن المنهج والبيانات أو الملاحظات وشروط النجاح والنتائج والقيود واربط كل ادعاء أساسي بدليل اختباره. يتناسب عمق التحقق مع المشروع والتخصص دون حجم عينة وطني ثابت؛ يجب توثيق النتائج والإجراءات في النسخة المقيمة."}, "anchors": [{"level": 0, "en": "Claims have no validation evidence.", "ar": "لا توجد أدلة تحقق للادعاءات."}, {"level": 1, "en": "Assertions or an isolated demonstration without a clear method or result record.", "ar": "تأكيدات أو عرض منفرد دون منهجية واضحة أو سجل نتائج."}, {"level": 2, "en": "A suitable validation activity records procedure and results for the main output.", "ar": "نشاط تحقق مناسب يوثق الإجراءات والنتائج للمخرج الرئيسي."}, {"level": 3, "en": "Core claims are tested against stated success conditions; results, failures and limitations are reported.", "ar": "اختبار الادعاءات الأساسية مقابل شروط النجاح المعلنة مع الإبلاغ عن النتائج والفشل والقيود."}, {"level": 4, "en": "Validation is repeatable, critically analyzed, and supported by a suitable baseline, triangulation, or robustness check.", "ar": "التحقق قابل للتكرار ومحلل نقدياً ومدعوم بخط أساس مناسب أو تثليث الأدلة أو فحص المتانة."}]}, {"code": "C5", "weight": 15, "label": {"en": "Innovation and Originality", "ar": "الابتكار والأصالة"}, "description": {"en": "State the contribution and compare it against at least two relevant prior works, alternatives, or established practices; distinguish adaptation, combination, and a new contribution using evidence. A justified improvement or context-specific adaptation can be valuable. Do not require proof that nobody worldwide has used the idea; comparison evidence must be in the assessed snapshot.", "ar": "حدد المساهمة وقارنها بعملين سابقين أو بديلين أو ممارستين معتمدتين على الأقل وميز بالأدلة بين التكييف والتركيب والمساهمة الجديدة. التحسين المبرر أو التكييف السياقي ذو قيمة؛ لا تشترط إثبات الأسبقية العالمية وتوجد المقارنة في اللقطة المقيمة."}, "anchors": [{"level": 0, "en": "No identifiable contribution evidence.", "ar": "لا توجد أدلة مساهمة قابلة للتحديد."}, {"level": 1, "en": "Contribution is claimed but not distinguished from prior work.", "ar": "المساهمة مدعاة لكنها غير مميزة عن الأعمال السابقة."}, {"level": 2, "en": "A clear adaptation or improvement is identified against relevant alternatives.", "ar": "تكييف أو تحسين واضح محدد مقابل بدائل ذات صلة."}, {"level": 3, "en": "A justified distinctive combination, approach or improvement is supported by the comparison.", "ar": "تركيبة أو منهج أو تحسين مميز ومبرر تدعمه المقارنة."}, {"level": 4, "en": "The contribution’s advantage or new insight is demonstrated against the documented alternatives, without unsupported world-first claims.", "ar": "إثبات ميزة المساهمة أو الرؤية الجديدة مقابل البدائل الموثقة دون ادعاءات غير مدعومة بالأسبقية العالمية."}]}, {"code": "C6", "weight": 10, "label": {"en": "Impact and Practical Relevance", "ar": "الأثر والأهمية العملية"}, "description": {"en": "Identify at least one beneficiary and plausible use context; support the claimed benefit with a stakeholder observation, measured outcome, reasoned analysis, or feasibility evidence. Academic, social, environmental, or practical benefit qualifies; commercial potential is not mandatory. Distinguish demonstrated benefit from projected benefit at the evidence cutoff.", "ar": "حدد مستفيداً واحداً على الأقل وسياق استخدام معقولاً وادعم الفائدة بملاحظة صاحب مصلحة أو نتيجة مقاسة أو تحليل معلل أو دليل جدوى. تقبل الفائدة الأكاديمية والاجتماعية والبيئية والعملية دون اشتراط التجارة؛ ميز الفائدة المثبتة من المتوقعة عند موعد التسليم."}, "anchors": [{"level": 0, "en": "No plausible beneficiary or use.", "ar": "لا يوجد مستفيد أو استخدام معقول."}, {"level": 1, "en": "Benefit is vague or unsupported.", "ar": "الفائدة غامضة أو غير مدعومة."}, {"level": 2, "en": "A beneficiary, realistic use context and reasoned benefit are identified.", "ar": "تحديد مستفيد وسياق استخدام واقعي وفائدة معللة."}, {"level": 3, "en": "Stakeholder evidence, measured benefit or credible feasibility analysis supports the stated use.", "ar": "أدلة أصحاب المصلحة أو الفائدة المقاسة أو تحليل جدوى موثوق يدعم الاستخدام المعلن."}, {"level": 4, "en": "The benefit is demonstrated or strongly substantiated in context, with adoption/resource limitations and possible adverse effects considered.", "ar": "الفائدة مثبتة أو مدعومة بقوة في السياق مع مراعاة قيود التبني والموارد والآثار السلبية المحتملة."}]}, {"code": "C7", "weight": 5, "label": {"en": "Documentation and Reproducibility", "ar": "التوثيق وقابلية التكرار"}, "description": {"en": "Provide a navigable report and artifact index, requirements/prerequisites, and steps that let an informed reader inspect or repeat the main demonstration or analysis; document access limitations. Use a discipline-appropriate reproduction or inspection path. Do not require public release of restricted data; sufficient documentation must be in the same frozen submission.", "ar": "قدم تقريراً قابلاً للتصفح وفهرس مخرجات ومتطلبات وخطوات لفحص أو تكرار العرض أو التحليل الرئيسي مع توثيق قيود الوصول. استخدم مساراً مناسباً للتخصص دون اشتراط نشر البيانات المقيدة؛ يوجد التوثيق الكافي في اللقطة المجمدة نفسها."}, "anchors": [{"level": 0, "en": "Artifacts cannot be understood from the documentation.", "ar": "لا يمكن فهم المخرجات من التوثيق."}, {"level": 1, "en": "Important files, steps or prerequisites are unexplained.", "ar": "ملفات أو خطوات أو متطلبات أساسية مهمة غير مشروحة."}, {"level": 2, "en": "A usable report, file index and basic inspection/reproduction instructions exist.", "ar": "يوجد تقرير قابل للاستخدام وفهرس ملفات وتعليمات أساسية للفحص أو التكرار."}, {"level": 3, "en": "Clear structured instructions, prerequisites, evidence locators and known limitations allow an informed reader to follow the main result.", "ar": "تعليمات منظمة واضحة ومتطلبات ومحددات أدلة وقيود معروفة تتيح للقارئ المطلع متابعة النتيجة الرئيسية."}, {"level": 4, "en": "A demonstrated repeatable inspection/reproduction path and coherent artifact provenance support the central claims within disclosure limits.", "ar": "مسار مثبت قابل لتكرار الفحص أو التنفيذ ومصدرية مخرجات متماسكة يدعم الادعاءات الأساسية ضمن حدود الإفصاح."}]}], "levels": {"en": ["Not demonstrated", "Limited", "Meets declared expectations", "Strong", "Exemplary within the stated project scope"], "ar": ["غير مثبت", "محدود", "يلبي التوقعات المعلنة", "قوي", "نموذجي ضمن نطاق المشروع المعلن"]}, "calibration": {"en": "Choose the highest descriptor fully supported by frozen evidence. A suitable validation activity with recorded procedure and results supports C4 level 2; stated success conditions, tested core claims, failures and limitations support level 3. Counts alone do not establish exemplary quality. All level 2 gives 50; all level 3 gives 75. These are repository scores, not course grades. Common anchors support consistent use without establishing inter-rater reliability.", "ar": "اختر أعلى وصف تدعمه الأدلة المجمدة بالكامل. نشاط تحقق مناسب يوثق الإجراءات والنتائج يدعم المستوى 2 في C4؛ شروط النجاح المعلنة واختبار الادعاءات الأساسية والفشل والقيود تدعم المستوى 3. العدد وحده لا يثبت الجودة النموذجية. جميع المستويات 2 تعطي 50 وجميع المستويات 3 تعطي 75. هذه درجات المستودع وليست درجات المقرر. تدعم الأوصاف المشتركة اتساق الاستخدام دون إثبات موثوقية الاتفاق بين المقيمين."}}'::jsonb j) seed;
--> statement-breakpoint
CREATE FUNCTION app.evaluation_actor(reader uuid,sid uuid,sub uuid,mutating boolean,expected integer DEFAULT NULL,assignment_expected integer DEFAULT NULL) RETURNS app.projects LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,app AS $$
DECLARE a app.users;p app.projects;s app.project_submissions;v app.project_versions;
BEGIN
 p:=app.submission_actor(reader,sid,sub);a:=app.assignment_principal(reader,sid);
 IF a.role_code<>'faculty_supervisor' OR p.supervisor_id IS DISTINCT FROM reader THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='NOT_FOUND';END IF;
 SELECT * INTO s FROM app.project_submissions WHERE id=sub;SELECT * INTO v FROM app.project_versions WHERE id=s.version_id FOR UPDATE;
 IF mutating AND (p.current_version_id IS DISTINCT FROM v.id OR v.status<>'pending_review' OR sub IS DISTINCT FROM (SELECT id FROM app.project_submissions WHERE version_id=v.id ORDER BY round_number DESC LIMIT 1) OR expected IS DISTINCT FROM v.row_version OR assignment_expected IS DISTINCT FROM p.row_version OR EXISTS(SELECT 1 FROM app.review_records WHERE submission_id=sub)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='STALE_ROUND';END IF;
 RETURN p;
END $$;
REVOKE ALL ON FUNCTION app.evaluation_actor(uuid,uuid,uuid,boolean,integer,integer) FROM PUBLIC,capstone_runtime,capstone_jobs;
CREATE FUNCTION app.evaluation_read(reader uuid,sid uuid,sub uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,app AS $$
DECLARE p app.projects;result jsonb;sq integer;cq integer;disagreement boolean;
BEGIN
 p:=app.evaluation_actor(reader,sid,sub,false);
 SELECT quarter_points INTO sq FROM app.internal_assessments WHERE submission_id=sub AND layer='supervisor';SELECT quarter_points INTO cq FROM app.internal_assessments WHERE submission_id=sub AND layer='committee';
 SELECT EXISTS(SELECT 1 FROM app.internal_evaluation_issues i JOIN app.evaluation_cases c ON c.id=i.case_id WHERE c.submission_id=sub) INTO disagreement;
 SELECT coalesce(jsonb_agg(to_jsonb(a)-'university_id'-'project_id'-'version_id'||jsonb_build_object('total',a.quarter_points::numeric/4,'criteria',(SELECT jsonb_agg(to_jsonb(c)||jsonb_build_object('locators',(SELECT jsonb_agg(jsonb_build_object('file',l.file_id,'kind',l.kind,'reference',l.reference) ORDER BY ordinal) FROM app.internal_evidence_locators l WHERE l.assessment_id=a.id AND l.code=c.code)) ORDER BY c.code) FROM app.internal_criterion_scores c WHERE c.assessment_id=a.id)) ORDER BY a.layer),'[]') INTO result FROM app.internal_assessments a WHERE submission_id=sub;
 RETURN jsonb_build_object('submission',sub,'rubric',(SELECT config||jsonb_build_object('hash',config_hash) FROM app.rubric_versions WHERE code='CORE_V1'),'assessments',result,'supervisor',sq::numeric/4,'committee',cq::numeric/4,'internal',(2*sq+3*cq)::numeric/20,'disagreement',disagreement,'external',NULL);
END $$;
REVOKE ALL ON FUNCTION app.evaluation_read(uuid,uuid,uuid) FROM PUBLIC,capstone_jobs;GRANT EXECUTE ON FUNCTION app.evaluation_read(uuid,uuid,uuid) TO capstone_runtime;
--> statement-breakpoint
CREATE FUNCTION app.evaluation_prepare(reader uuid,sid uuid,sub uuid,expected integer,assignment_expected integer,payload jsonb,command uuid,payload_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,app AS $$
DECLARE p app.projects;r app.command_receipts;layer_value text:=payload->>'layer';c jsonb;l jsonb;n text;seen text[]:='{}';normalized text[]:='{}';lv numeric;ref text;files jsonb;record app.internal_assessments;
BEGIN
 p:=app.evaluation_actor(reader,sid,sub,false);
 SELECT * INTO r FROM app.command_receipts WHERE actor_id=reader AND command_id=command;
 IF r.command_id IS NOT NULL THEN IF r.action<>'evaluation.'||layer_value OR r.payload_digest IS DISTINCT FROM payload_hash THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='IDEMPOTENCY_CONFLICT';END IF;RETURN jsonb_build_object('completed',r.result->>'scope');END IF;
 p:=app.evaluation_actor(reader,sid,sub,true,expected,assignment_expected);
 IF layer_value NOT IN ('supervisor','committee') OR layer_value IS NULL OR EXISTS(SELECT 1 FROM jsonb_object_keys(payload) k WHERE k NOT IN ('layer','criteria','overall','calibration','members','assessedOn','attestation')) OR payload->'calibration' IS DISTINCT FROM 'true'::jsonb OR jsonb_typeof(payload->'overall') IS DISTINCT FROM 'string' OR char_length(btrim(payload->>'overall')) NOT BETWEEN 50 AND 2000 OR jsonb_typeof(payload->'criteria') IS DISTINCT FROM 'array' OR jsonb_array_length(payload->'criteria')<>7 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='INVALID_ASSESSMENT';END IF;
 SELECT * INTO record FROM app.internal_assessments WHERE submission_id=sub AND layer=layer_value;
 IF record.id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ALREADY_FINALIZED';END IF;
 IF layer_value='committee' AND NOT EXISTS(SELECT 1 FROM app.internal_assessments WHERE submission_id=sub AND layer='supervisor') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='SUPERVISOR_REQUIRED';END IF;
 IF layer_value='committee' THEN
  IF jsonb_typeof(payload->'members') IS DISTINCT FROM 'array' OR jsonb_array_length(payload->'members') NOT BETWEEN 2 AND 50 OR payload->'attestation' IS DISTINCT FROM 'true'::jsonb OR coalesce(payload->>'assessedOn','') !~ '^\d{4}-\d{2}-\d{2}$' OR (payload->>'assessedOn')::date>(clock_timestamp() AT TIME ZONE 'UTC')::date THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='INVALID_COMMITTEE';END IF;
  FOR c IN SELECT value FROM jsonb_array_elements(payload->'members') LOOP
   IF jsonb_typeof(c)<>'string' OR char_length(btrim(c#>>'{}')) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='INVALID_MEMBERS';END IF;
   n:=lower(regexp_replace(btrim(normalize(c#>>'{}',NFKC)),'[[:space:]]+',' ','g'));
   IF n=ANY(normalized) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='DUPLICATE_MEMBERS';END IF;normalized:=array_append(normalized,n);
  END LOOP;
 ELSE IF payload->'members' IS DISTINCT FROM '[]'::jsonb OR payload->'assessedOn' IS DISTINCT FROM 'null'::jsonb OR payload->'attestation' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='INVALID_PROVENANCE';END IF;END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(payload->'criteria') LOOP
  IF jsonb_typeof(c)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(c) k WHERE k NOT IN ('code','level','comment','locators')) OR coalesce(c->>'code','') !~ '^C[1-7]$' OR c->>'code'=ANY(seen) OR jsonb_typeof(c->'level') IS DISTINCT FROM 'number' OR jsonb_typeof(c->'comment') IS DISTINCT FROM 'string' OR jsonb_typeof(c->'locators') IS DISTINCT FROM 'array' OR jsonb_array_length(c->'locators') NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='INVALID_CRITERION';END IF;
  seen:=array_append(seen,c->>'code');lv:=(c->>'level')::numeric;
  IF lv<0 OR lv>4 OR lv<>trunc(lv) OR char_length(btrim(c->>'comment'))>1000 OR (lv IN (0,4) AND char_length(btrim(c->>'comment'))<20) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='INVALID_LEVEL_COMMENT';END IF;
  FOR l IN SELECT value FROM jsonb_array_elements(c->'locators') LOOP
   ref:=btrim(l->>'reference');
   IF jsonb_typeof(l)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(l) k WHERE k NOT IN ('file','kind','reference')) OR coalesce(l->>'kind','') NOT IN ('page','section','figure','test','lines') OR jsonb_typeof(l->'reference') IS DISTINCT FROM 'string' OR char_length(ref) NOT BETWEEN 1 AND 200 OR ((l->>'kind') IN ('page','lines') AND ref !~ '^[1-9]\d*(-[1-9]\d*)?$') OR NOT EXISTS(SELECT 1 FROM app.submission_files WHERE submission_id=sub AND file_id=(l->>'file')::uuid) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='INVALID_LOCATOR';END IF;
   PERFORM app.submission_native_read(reader,sid,p.id,p.current_version_id,sub,(l->>'file')::uuid);
  END LOOP;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM app.rubric_versions WHERE code='CORE_V1' AND kind='internal' AND schema_version=1 AND config_hash=encode(sha256(convert_to(config::text,'UTF8')),'hex')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='RUBRIC_INTEGRITY';END IF;
 SELECT jsonb_agg(jsonb_build_object('key',o.storage_key,'size',o.size_bytes,'sha256',o.sha256) ORDER BY o.id) INTO files FROM app.submission_files f JOIN app.storage_objects o ON o.id=f.storage_object_id AND o.project_id=f.project_id AND o.university_id=f.university_id WHERE f.submission_id=sub;
 RETURN jsonb_build_object('files',files);
END $$;
REVOKE ALL ON FUNCTION app.evaluation_prepare(uuid,uuid,uuid,integer,integer,jsonb,uuid,text) FROM PUBLIC,capstone_jobs;GRANT EXECUTE ON FUNCTION app.evaluation_prepare(uuid,uuid,uuid,integer,integer,jsonb,uuid,text) TO capstone_runtime;
--> statement-breakpoint
CREATE FUNCTION app.evaluation_commit(reader uuid,sid uuid,sub uuid,expected integer,assignment_expected integer,payload jsonb,command uuid,payload_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,app AS $$
DECLARE prepared jsonb;p app.projects;s app.project_submissions;cid uuid;aid uuid:=gen_random_uuid();ev uuid:=gen_random_uuid();t timestamptz:=clock_timestamp();quarter integer:=0;c jsonb;l jsonb;ord integer;r app.rubric_versions;result jsonb;sup app.internal_assessments;
BEGIN
 prepared:=app.evaluation_prepare(reader,sid,sub,expected,assignment_expected,payload,command,payload_hash);IF prepared ? 'completed' THEN RETURN (prepared->>'completed')::jsonb;END IF;
 SELECT * INTO s FROM app.project_submissions WHERE id=sub;SELECT * INTO p FROM app.projects WHERE id=s.project_id;SELECT * INTO r FROM app.rubric_versions WHERE code='CORE_V1';
 INSERT INTO app.evaluation_cases(university_id,project_id,version_id,submission_id,rubric_code) VALUES(p.university_id,p.id,s.version_id,sub,'CORE_V1') ON CONFLICT(submission_id) DO NOTHING;
 SELECT id INTO cid FROM app.evaluation_cases WHERE submission_id=sub;
 FOR c IN SELECT value FROM jsonb_array_elements(payload->'criteria') LOOP quarter:=quarter+(ARRAY[10,20,20,20,15,10,5])[(substring(c->>'code' FROM 2))::integer]*(c->>'level')::integer;END LOOP;
 INSERT INTO app.internal_assessments(id,university_id,project_id,version_id,submission_id,case_id,layer,rubric_code,rubric_hash,recorded_by,recorded_at,finalized_at,quarter_points,overall_comment,calibration_ack,member_names,assessed_on,attestation) VALUES(aid,p.university_id,p.id,s.version_id,sub,cid,payload->>'layer',r.code,r.config_hash,reader,t,t,quarter,btrim(payload->>'overall'),true,coalesce((SELECT jsonb_agg(btrim(value#>>'{}') ORDER BY ordinal) FROM jsonb_array_elements(payload->'members') WITH ORDINALITY m(value,ordinal)),'[]'),(payload->>'assessedOn')::date,(payload->>'attestation')::boolean);
 FOR c IN SELECT value FROM jsonb_array_elements(payload->'criteria') LOOP
  INSERT INTO app.internal_criterion_scores VALUES(aid,c->>'code',(c->>'level')::integer,btrim(c->>'comment'));ord:=0;
  FOR l IN SELECT value FROM jsonb_array_elements(c->'locators') LOOP ord:=ord+1;INSERT INTO app.internal_evidence_locators VALUES(p.university_id,p.id,s.version_id,sub,aid,c->>'code',ord,(l->>'file')::uuid,l->>'kind',btrim(l->>'reference'));END LOOP;
 END LOOP;
 IF payload->>'layer'='committee' THEN
  SELECT * INTO sup FROM app.internal_assessments WHERE submission_id=sub AND layer='supervisor';
  IF abs(sup.quarter_points-quarter)>=60 OR EXISTS(SELECT 1 FROM app.internal_criterion_scores a JOIN app.internal_criterion_scores b ON a.code=b.code WHERE a.assessment_id=sup.id AND b.assessment_id=aid AND abs(a.level-b.level)>=2) THEN INSERT INTO app.internal_evaluation_issues(case_id,supervisor_id,committee_id,kind,created_at) VALUES(cid,sup.id,aid,'internal_disagreement',t);END IF;
 END IF;
 result:=jsonb_build_object('id',aid,'submission',sub,'layer',payload->>'layer','total',quarter::numeric/4,'rubric','CORE_V1');
 INSERT INTO app.audit_logs(id,actor_id,actor_role,university_id,action,object_type,object_id,project_id,version_id,correlation_id,event_key,after_state) VALUES(ev,reader,'faculty_supervisor',p.university_id,'evaluation.'||(payload->>'layer'),'internal_assessment',aid,p.id,s.version_id,command,ev,jsonb_build_object('scope',jsonb_build_object('submission',sub,'assessment',aid,'layer',payload->>'layer','rubric',r.code,'rubricHash',r.config_hash,'total',quarter::numeric/4,'utc',t)::text));
 INSERT INTO app.command_receipts(actor_id,command_id,action,payload_digest,audit_id,result) VALUES(reader,command,'evaluation.'||(payload->>'layer'),payload_hash,ev,jsonb_build_object('scope',result::text));RETURN result;
END $$;
REVOKE ALL ON FUNCTION app.evaluation_commit(uuid,uuid,uuid,integer,integer,jsonb,uuid,text) FROM PUBLIC,capstone_jobs;GRANT EXECUTE ON FUNCTION app.evaluation_commit(uuid,uuid,uuid,integer,integer,jsonb,uuid,text) TO capstone_runtime;
